import { useEffect, useMemo, useState } from "react";
import { Link, useLocation } from "wouter";
import { toast } from "sonner";
import {
  AlertTriangle,
  ArrowDownRight,
  ArrowUpRight,
  Boxes,
  ClipboardList,
  FileSpreadsheet,
  FileText,
  LayoutDashboard,
  PackageCheck,
  Plus,
  Printer,
  Receipt,
  RefreshCw,
  ShieldCheck,
  ShoppingCart,
  Truck,
  Users,
  WalletCards,
} from "lucide-react";
import DashboardLayout from "@/components/DashboardLayout";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Separator } from "@/components/ui/separator";
import { trpc } from "@/lib/trpc";

const blue = "#0b2b71";
const cyan = "#62d8ff";

type CurrencyWindow = Window & { __ANKOLE_CURRENCY__?: string };
function ugx(value: number | null | undefined) {
  const currency = typeof window !== "undefined" ? (window as CurrencyWindow).__ANKOLE_CURRENCY__ ?? "UGX" : "UGX";
  return `${currency} ${new Intl.NumberFormat("en-UG").format(value ?? 0)}`;
}

function dateLabel(value: Date | string | number | null | undefined) {
  if (!value) return "—";
  return new Date(value).toLocaleDateString("en-UG", { day: "2-digit", month: "short", year: "numeric" });
}

function Status({ children, tone = "default" }: { children: React.ReactNode; tone?: "default" | "green" | "amber" | "red" }) {
  const styles = { default: "border-slate-400/40 bg-white/10 text-slate-100", green: "border-emerald-300/40 bg-emerald-400/10 text-emerald-200", amber: "border-amber-300/40 bg-amber-400/10 text-amber-100", red: "border-rose-300/40 bg-rose-400/10 text-rose-100" };
  return <span className={`inline-flex items-center rounded-full border px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider ${styles[tone]}`}>{children}</span>;
}

function BlueprintFrame({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return <div className={`relative overflow-hidden rounded-sm border border-white/15 bg-[#071f56]/70 shadow-[0_24px_60px_rgba(0,0,0,0.22)] ${className}`}><div className="pointer-events-none absolute inset-0 opacity-20 [background-image:linear-gradient(rgba(255,255,255,0.08)_1px,transparent_1px),linear-gradient(90deg,rgba(255,255,255,0.08)_1px,transparent_1px)] [background-size:20px_20px]" />{children}</div>;
}

function KpiCard({ label, value, detail, icon: Icon, accent = cyan }: { label: string; value: string; detail: string; icon: React.ElementType; accent?: string }) {
  return <BlueprintFrame className="p-5"><div className="relative flex items-start justify-between"><div><p className="text-[10px] font-black uppercase tracking-[0.22em] text-white/55">{label}</p><p className="mt-3 text-2xl font-black tracking-tight text-white">{value}</p><p className="mt-1 text-xs text-white/55">{detail}</p></div><div className="flex h-10 w-10 items-center justify-center border border-white/20 bg-white/5" style={{ color: accent }}><Icon className="h-5 w-5" /></div></div><div className="relative mt-5 h-px bg-white/10"><span className="absolute left-0 top-0 h-px w-1/3" style={{ backgroundColor: accent }} /></div></BlueprintFrame>;
}

function SectionHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="mb-6 flex flex-col justify-between gap-4 border-b border-white/15 pb-5 md:flex-row md:items-end"><div><p className="mb-2 text-[10px] font-black uppercase tracking-[0.3em] text-[#62d8ff]">{eyebrow}</p><h1 className="text-3xl font-black tracking-tight text-white md:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-white/55">{description}</p></div>{action}</div>;
}

function TableShell({ children }: { children: React.ReactNode }) {
  return <div className="relative overflow-x-auto"><table className="w-full text-left text-sm"><tbody>{children}</tbody></table></div>;
}

function TableHead({ children }: { children: React.ReactNode }) {
  return <tr className="border-b border-white/15 text-[10px] font-black uppercase tracking-[0.16em] text-white/45">{children}</tr>;
}

function TableCell({ children, className = "", colSpan }: { children?: React.ReactNode; className?: string; colSpan?: number }) {
  return <td colSpan={colSpan} className={`px-4 py-3 ${className}`}>{children}</td>;
}

function Panel({ title, eyebrow, children, className = "" }: { title: string; eyebrow?: string; children: React.ReactNode; className?: string }) {
  return <Card className={`border-white/15 bg-[#071f56]/75 text-white shadow-none ${className}`}><CardHeader className="relative border-b border-white/10 px-5 py-4"><div>{eyebrow && <p className="mb-1 text-[9px] font-black uppercase tracking-[0.2em] text-[#62d8ff]">{eyebrow}</p>}<CardTitle className="text-base font-black tracking-tight">{title}</CardTitle></div></CardHeader><CardContent className="relative p-0">{children}</CardContent></Card>;
}

function DashboardView() {
  const query = trpc.reporting.dashboard.useQuery(undefined, { staleTime: 20_000 });
  const data = query.data;
  const [, navigate] = useLocation();
  const refresh = () => void query.refetch();
  return <div><SectionHeader eyebrow="Control room / overview" title="Operations dashboard" description="A live view of stock integrity, sales velocity, cash collection, and exception points across the beverage operation." action={<Button onClick={refresh} variant="outline" className="border-white/20 bg-white/5 text-white hover:bg-white/10"><RefreshCw className="mr-2 h-4 w-4" />Refresh data</Button>} />
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      <KpiCard label="Active products" value={String(data?.totals.products ?? 0)} detail="Configured sellable SKUs" icon={Boxes} />
      <KpiCard label="Stock on hand" value={String(data?.totals.stockUnits ?? 0)} detail={ugx(data?.totals.stockValue)} icon={PackageCheck} accent="#9bff9b" />
      <KpiCard label="Today revenue" value={ugx(data?.totals.todayRevenue)} detail={`${data?.totals.todaySales ?? 0} completed invoices`} icon={Receipt} accent="#ffc66d" />
      <KpiCard label="Outstanding" value={ugx(data?.totals.outstanding)} detail="Customer credit balance" icon={WalletCards} accent="#ff8ea1" />
    </div>
    <div className="mt-6 grid gap-5 xl:grid-cols-[1.25fr_0.75fr]">
      <Panel eyebrow="Exception queue" title="Low-stock watchlist"><TableShell><TableHead><TableCell>SKU / product</TableCell><TableCell>Available</TableCell><TableCell>Reorder point</TableCell><TableCell>Status</TableCell></TableHead>{(data?.lowStock ?? []).map((product) => <tr key={product.id} className="border-b border-white/10 text-white/80"><TableCell><p className="font-bold text-white">{product.name}</p><p className="text-xs text-white/45">{product.sku}</p></TableCell><TableCell className="font-mono">{product.currentStock}</TableCell><TableCell className="font-mono">{product.reorderLevel}</TableCell><TableCell><Status tone={product.currentStock === 0 ? "red" : "amber"}>{product.currentStock === 0 ? "Out of stock" : "Reorder"}</Status></TableCell></tr>)}{!data?.lowStock?.length && <tr><TableCell className="py-10 text-center text-white/45" colSpan={4}>No low-stock exceptions.</TableCell></tr>}</TableShell></Panel>
      <Panel eyebrow="Quick actions" title="Move with intent"><div className="grid gap-3 p-5 sm:grid-cols-2 xl:grid-cols-1">{[["/sales", "Record sale", Receipt], ["/purchases", "Receive stock", Truck], ["/inventory", "Review stock", Boxes], ["/reports", "Open reports", FileText]].map(([path, label, Icon]) => <button key={String(path)} onClick={() => navigate(String(path))} className="group flex items-center gap-3 border border-white/15 bg-white/5 p-4 text-left transition hover:border-[#62d8ff]/60 hover:bg-white/10"><span className="flex h-9 w-9 items-center justify-center border border-[#62d8ff]/30 text-[#62d8ff]"><Icon className="h-4 w-4" /></span><span><span className="block text-sm font-bold text-white">{String(label)}</span><span className="text-xs text-white/45">Open controlled workflow</span></span><ArrowUpRight className="ml-auto h-4 w-4 text-white/30 transition group-hover:text-[#62d8ff]" /></button>)}</div></Panel>
    </div>
    <div className="mt-5 grid gap-5 xl:grid-cols-2"><Panel eyebrow="Sales ledger" title="Recent completed sales"><TableShell><TableHead><TableCell>Invoice</TableCell><TableCell>Date</TableCell><TableCell>Total</TableCell><TableCell>Balance</TableCell><TableCell>Document</TableCell></TableHead>{(data?.recentSales ?? []).map((sale) => <tr key={sale.id} className="border-b border-white/10 text-white/80"><TableCell className="font-mono text-[#62d8ff]">{sale.invoiceNumber}</TableCell><TableCell>{dateLabel(sale.createdAt)}</TableCell><TableCell className="font-semibold">{ugx(sale.totalAmount)}</TableCell><TableCell>{sale.balance > 0 ? <Status tone="amber">{ugx(sale.balance)}</Status> : <Status tone="green">Paid</Status>}</TableCell><TableCell><Link href={`/invoices/${sale.id}`} className="text-xs font-bold text-[#62d8ff] hover:text-white">Open</Link></TableCell></tr>)}{!data?.recentSales?.length && <tr><TableCell className="py-8 text-center text-white/45" colSpan={5}>No sales recorded yet.</TableCell></tr>}</TableShell></Panel><Panel eyebrow="Demand signal" title="Top-selling products"><div className="space-y-4 p-5">{(data?.topProducts ?? []).map((product, index) => <div key={product?.id ?? index} className="flex items-center gap-3"><div className="flex h-8 w-8 items-center justify-center border border-white/15 font-mono text-xs text-[#62d8ff]">0{index + 1}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-white">{product?.name ?? "Unknown product"}</p><div className="mt-2 h-1 bg-white/10"><div className="h-1 bg-[#62d8ff]" style={{ width: `${Math.min(100, ((product?.quantity ?? 0) / Math.max(1, data?.topProducts?.[0]?.quantity ?? 1)) * 100)}%` }} /></div></div><span className="font-mono text-xs text-white/55">{product?.quantity ?? 0} units</span></div>)}{!data?.topProducts?.length && <p className="py-6 text-center text-sm text-white/45">Sales movement data will appear here.</p>}</div></Panel></div>
  </div>;
}

function InvoiceView({ saleId }: { saleId: number }) {
  const details = trpc.operations.saleDetails.useQuery({ saleId });
  const sale = details.data?.sale;
  return <div><SectionHeader eyebrow="Document / confirmed sale" title={sale?.invoiceNumber ?? "Invoice"} description="This document is generated from server-calculated sale lines. Use the print action for a receipt-ready copy." action={<div className="flex gap-2"><Button onClick={() => window.print()} className="bg-[#62d8ff] font-black text-[#061a4a] hover:bg-[#91e5ff]"><Printer className="mr-2 h-4 w-4" />Print receipt</Button><Link href="/" className="inline-flex h-10 items-center border border-white/20 bg-white/5 px-4 text-sm font-bold text-white hover:bg-white/10">Back</Link></div>} /><Panel eyebrow="Invoice / receipt" title={sale?.invoiceNumber ?? "Loading"}><div className="grid gap-4 p-5 sm:grid-cols-4"><div><p className="text-xs text-white/45">Date</p><p className="mt-1 font-bold">{dateLabel(sale?.createdAt)}</p></div><div><p className="text-xs text-white/45">Customer</p><p className="mt-1 font-bold">#{sale?.customerId ?? "—"}</p></div><div><p className="text-xs text-white/45">Status</p><p className="mt-1"><Status tone={sale?.status === "COMPLETED" ? "green" : "amber"}>{sale?.status ?? "Loading"}</Status></p></div><div><p className="text-xs text-white/45">Due date</p><p className="mt-1 font-bold">{dateLabel(sale?.dueDate)}</p></div></div><TableShell><TableHead><TableCell>Product</TableCell><TableCell>SKU</TableCell><TableCell>Qty</TableCell><TableCell>Unit price</TableCell><TableCell>Line total</TableCell></TableHead>{(details.data?.items ?? []).map((item) => <tr key={item.id} className="border-b border-white/10 text-white/80"><TableCell className="font-bold text-white">{item.productName}</TableCell><TableCell className="font-mono text-[#62d8ff]">{item.sku}</TableCell><TableCell>{item.quantity}</TableCell><TableCell>{ugx(item.unitPrice)}</TableCell><TableCell>{ugx(item.lineTotal)}</TableCell></tr>)}</TableShell><div className="grid gap-2 border-t border-white/10 p-5 text-right"><p className="text-sm text-white/55">Subtotal: <span className="font-bold text-white">{ugx(sale?.subtotal)}</span></p><p className="text-sm text-white/55">Discount: <span className="font-bold text-white">{ugx(sale?.discount)}</span></p><p className="text-lg font-black text-[#62d8ff]">Total: {ugx(sale?.totalAmount)}</p><p className="text-sm text-white/55">Balance: <span className="font-bold text-white">{ugx(sale?.balance)}</span></p></div></Panel></div>;
}

function CatalogView() {
  const options = useMemo(() => ({}), []);
  const products = trpc.catalog.products.useQuery(options);
  const categories = trpc.catalog.categories.useQuery();
  const units = trpc.catalog.units.useQuery();
  const packagings = trpc.catalog.packagings.useQuery();
  const createProduct = trpc.catalog.createProduct.useMutation({ onSuccess: () => { toast.success("Product added to catalog"); void products.refetch(); setForm({ sku: "", name: "", categoryId: "", unitId: "", packagingId: "", costPrice: "", sellingPrice: "", reorderLevel: "", expiryTracking: false }); }, onError: (error) => toast.error(error.message) });
  const updateProduct = trpc.catalog.updateProduct.useMutation({ onSuccess: () => { toast.success("Product configuration updated"); void products.refetch(); }, onError: (error) => toast.error(error.message) });
  const createCategory = trpc.catalog.createCategory.useMutation({ onSuccess: () => { toast.success("Category added"); void categories.refetch(); setCategoryName(""); }, onError: (error) => toast.error(error.message) });
  const createUnit = trpc.catalog.createUnit.useMutation({ onSuccess: () => { toast.success("Unit added"); void units.refetch(); setUnitName(""); setUnitSymbol(""); }, onError: (error) => toast.error(error.message) });
  const createPackaging = trpc.catalog.createPackaging.useMutation({ onSuccess: () => { toast.success("Packaging added"); void packagings.refetch(); setPackagingName(""); }, onError: (error) => toast.error(error.message) });
  const updateCategory = trpc.catalog.updateCategory.useMutation({ onSuccess: () => void categories.refetch(), onError: (error) => toast.error(error.message) });
  const updateUnit = trpc.catalog.updateUnit.useMutation({ onSuccess: () => void units.refetch(), onError: (error) => toast.error(error.message) });
  const updatePackaging = trpc.catalog.updatePackaging.useMutation({ onSuccess: () => void packagings.refetch(), onError: (error) => toast.error(error.message) });
  const [categoryName, setCategoryName] = useState(""); const [unitName, setUnitName] = useState(""); const [unitSymbol, setUnitSymbol] = useState(""); const [packagingName, setPackagingName] = useState("");
  const [form, setForm] = useState({ sku: "", name: "", categoryId: "", unitId: "", packagingId: "", costPrice: "", sellingPrice: "", reorderLevel: "", expiryTracking: false });
  const submit = (event: React.FormEvent) => { event.preventDefault(); createProduct.mutate({ sku: form.sku, name: form.name, categoryId: Number(form.categoryId), unitId: Number(form.unitId), packagingId: form.packagingId ? Number(form.packagingId) : undefined, costPrice: Number(form.costPrice), sellingPrice: Number(form.sellingPrice), reorderLevel: Number(form.reorderLevel), expiryTracking: form.expiryTracking, isActive: true }); };
  return <div><SectionHeader eyebrow="Catalog / master data" title="Product architecture" description="Configure sellable SKUs, units, packaging, and reorder policy. Product prices and status are validated by the server at the point of sale." /><div className="grid gap-5 xl:grid-cols-[0.72fr_1.28fr]"><Panel eyebrow="New master record" title="Add product"><form onSubmit={submit} className="space-y-4 p-5"><div className="grid grid-cols-2 gap-3"><label className="block text-xs font-bold uppercase tracking-wider text-white/55">SKU<Input required value={form.sku} onChange={(e) => setForm({ ...form, sku: e.target.value })} className="mt-2 border-white/15 bg-white/5 text-white" /></label><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Product name<Input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="mt-2 border-white/15 bg-white/5 text-white" /></label></div><div className="grid grid-cols-2 gap-3"><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Category<select required value={form.categoryId} onChange={(e) => setForm({ ...form, categoryId: e.target.value })} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-2 text-xs text-white"><option value="">Select</option>{(categories.data ?? []).map((row) => <option key={row.id} value={row.id}>{row.name}</option>)}</select></label><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Unit<select required value={form.unitId} onChange={(e) => setForm({ ...form, unitId: e.target.value })} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-2 text-xs text-white"><option value="">Select</option>{(units.data ?? []).map((row) => <option key={row.id} value={row.id}>{row.name} ({row.symbol})</option>)}</select></label></div><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Packaging<select value={form.packagingId} onChange={(e) => setForm({ ...form, packagingId: e.target.value })} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-2 text-xs text-white"><option value="">Optional</option>{(packagings.data ?? []).map((row) => <option key={row.id} value={row.id}>{row.name}</option>)}</select></label><label className="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-white/55"><input type="checkbox" checked={form.expiryTracking} onChange={(e) => setForm({ ...form, expiryTracking: e.target.checked })} /> Track expiry dates</label><div className="grid grid-cols-3 gap-3"><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Cost<Input required type="number" min="0" value={form.costPrice} onChange={(e) => setForm({ ...form, costPrice: e.target.value })} className="mt-2 border-white/15 bg-white/5 text-white" /></label><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Sell price<Input required type="number" min="0" value={form.sellingPrice} onChange={(e) => setForm({ ...form, sellingPrice: e.target.value })} className="mt-2 border-white/15 bg-white/5 text-white" /></label><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Reorder<Input required type="number" min="0" value={form.reorderLevel} onChange={(e) => setForm({ ...form, reorderLevel: e.target.value })} className="mt-2 border-white/15 bg-white/5 text-white" /></label></div><Button disabled={createProduct.isPending} className="w-full bg-[#62d8ff] font-black text-[#061a4a] hover:bg-[#91e5ff]"><Plus className="mr-2 h-4 w-4" />Create SKU</Button></form></Panel><Panel eyebrow="Current catalog" title={`${products.data?.length ?? 0} configured products`}><TableShell><TableHead><TableCell>SKU / product</TableCell><TableCell>Category</TableCell><TableCell>Unit</TableCell><TableCell>Cost</TableCell><TableCell>Sell</TableCell><TableCell>Status / controls</TableCell></TableHead>{(products.data ?? []).map((product) => <tr key={product.id} className="border-b border-white/10 text-white/80"><TableCell><p className="font-bold text-white">{product.name}</p><p className="font-mono text-xs text-[#62d8ff]">{product.sku}</p></TableCell><TableCell>{product.categoryName ?? "—"}</TableCell><TableCell>{product.unitName ?? "—"}</TableCell><TableCell>{ugx(product.costPrice)}</TableCell><TableCell>{ugx(product.sellingPrice)}</TableCell><TableCell><div className="flex flex-wrap items-center gap-2"><Status tone={product.isActive ? "green" : "red"}>{product.isActive ? "Active" : "Inactive"}</Status>{product.expiryTracking && <Status tone="amber">Expiry</Status>}<Button size="sm" variant="outline" onClick={() => updateProduct.mutate({ id: product.id, isActive: !product.isActive })} className="border-white/20 bg-white/5 text-[10px] text-white hover:bg-white/10">{product.isActive ? "Deactivate" : "Activate"}</Button><Button size="sm" variant="outline" onClick={() => updateProduct.mutate({ id: product.id, expiryTracking: !product.expiryTracking })} className="border-white/20 bg-white/5 text-[10px] text-white hover:bg-white/10">Expiry</Button><Button size="sm" variant="outline" onClick={() => { const next = window.prompt("New selling price (UGX)", String(product.sellingPrice)); if (next !== null && next !== "") updateProduct.mutate({ id: product.id, sellingPrice: Number(next) }); }} className="border-white/20 bg-white/5 text-[10px] text-white hover:bg-white/10">Edit price</Button></div></TableCell></tr>)}</TableShell></Panel></div><div className="mt-5 grid gap-5 lg:grid-cols-3"><Panel eyebrow="Categories" title="Product categories"><form onSubmit={(event) => { event.preventDefault(); createCategory.mutate({ name: categoryName }); }} className="flex gap-2 border-b border-white/10 p-4"><Input required value={categoryName} onChange={(e) => setCategoryName(e.target.value)} placeholder="Category name" className="border-white/15 bg-white/5 text-white placeholder:text-white/25" /><Button size="sm" className="bg-[#62d8ff] text-[#061a4a]"><Plus className="h-4 w-4" /></Button></form><div className="space-y-2 p-4">{(categories.data ?? []).map((row) => <div key={row.id} className="flex items-center justify-between gap-2 border border-white/10 bg-white/5 p-3"><span className="text-sm text-white">{row.name}</span><Button size="sm" variant="outline" onClick={() => updateCategory.mutate({ id: row.id, isActive: !row.isActive })} className="border-white/20 bg-transparent text-[10px] text-white">{row.isActive ? "Disable" : "Enable"}</Button></div>)}</div></Panel><Panel eyebrow="Units" title="Units of measure"><form onSubmit={(event) => { event.preventDefault(); createUnit.mutate({ name: unitName, symbol: unitSymbol }); }} className="grid grid-cols-[1fr_0.5fr_auto] gap-2 border-b border-white/10 p-4"><Input required value={unitName} onChange={(e) => setUnitName(e.target.value)} placeholder="Name" className="border-white/15 bg-white/5 text-white placeholder:text-white/25" /><Input required value={unitSymbol} onChange={(e) => setUnitSymbol(e.target.value)} placeholder="Symbol" className="border-white/15 bg-white/5 text-white placeholder:text-white/25" /><Button size="sm" className="bg-[#62d8ff] text-[#061a4a]"><Plus className="h-4 w-4" /></Button></form><div className="space-y-2 p-4">{(units.data ?? []).map((row) => <div key={row.id} className="flex items-center justify-between gap-2 border border-white/10 bg-white/5 p-3"><span className="text-sm text-white">{row.name} · {row.symbol}</span><Button size="sm" variant="outline" onClick={() => updateUnit.mutate({ id: row.id, isActive: !row.isActive })} className="border-white/20 bg-transparent text-[10px] text-white">{row.isActive ? "Disable" : "Enable"}</Button></div>)}</div></Panel><Panel eyebrow="Packaging" title="Packaging types"><form onSubmit={(event) => { event.preventDefault(); createPackaging.mutate({ name: packagingName }); }} className="flex gap-2 border-b border-white/10 p-4"><Input required value={packagingName} onChange={(e) => setPackagingName(e.target.value)} placeholder="Packaging name" className="border-white/15 bg-white/5 text-white placeholder:text-white/25" /><Button size="sm" className="bg-[#62d8ff] text-[#061a4a]"><Plus className="h-4 w-4" /></Button></form><div className="space-y-2 p-4">{(packagings.data ?? []).map((row) => <div key={row.id} className="flex items-center justify-between gap-2 border border-white/10 bg-white/5 p-3"><span className="text-sm text-white">{row.name}</span><Button size="sm" variant="outline" onClick={() => updatePackaging.mutate({ id: row.id, isActive: !row.isActive })} className="border-white/20 bg-transparent text-[10px] text-white">{row.isActive ? "Disable" : "Enable"}</Button></div>)}</div></Panel></div></div>;
}

function InventoryView() {
  const productFilter = useMemo(() => ({}), []);
  const products = trpc.catalog.products.useQuery(productFilter);
  const adjustments = trpc.operations.adjustments.useQuery();
  const alerts = trpc.operations.inventoryAlerts.useQuery();
  const requestAdjustment = trpc.operations.requestAdjustment.useMutation({ onSuccess: () => { toast.success("Adjustment submitted for approval"); void adjustments.refetch(); }, onError: (error) => toast.error(error.message) });
  const recordLoss = trpc.operations.recordStockLoss.useMutation({ onSuccess: () => { toast.success("Stock loss recorded"); void alerts.refetch(); void products.refetch(); setLoss({ productId: "", movementType: "DAMAGE", quantity: "", reason: "" }); }, onError: (error) => toast.error(error.message) });
  const [form, setForm] = useState({ productId: "", adjustmentType: "OUT" as "IN" | "OUT", quantity: "", reason: "" });
  const [loss, setLoss] = useState({ productId: "", movementType: "DAMAGE" as "DAMAGE" | "EXPIRY" | "LOSS", quantity: "", reason: "" });
  const submit = (event: React.FormEvent) => { event.preventDefault(); requestAdjustment.mutate({ productId: Number(form.productId), adjustmentType: form.adjustmentType, quantity: Number(form.quantity), reason: form.reason }); };
  const submitLoss = (event: React.FormEvent) => { event.preventDefault(); recordLoss.mutate({ productId: Number(loss.productId), movementType: loss.movementType, quantity: Number(loss.quantity), reason: loss.reason }); };
  return <div><SectionHeader eyebrow="Inventory / control" title="Stock control" description="Current quantity is authoritative in the product ledger; every receipt, sale, return, and approved adjustment also leaves an immutable movement record." /><div className="grid gap-5 xl:grid-cols-[1.4fr_0.6fr]"><Panel eyebrow="Authoritative quantity ledger" title="Available stock"><TableShell><TableHead><TableCell>SKU / product</TableCell><TableCell>On hand</TableCell><TableCell>Reorder</TableCell><TableCell>Cost value</TableCell><TableCell>State</TableCell></TableHead>{(products.data ?? []).map((product) => <tr key={product.id} className="border-b border-white/10 text-white/80"><TableCell><p className="font-bold text-white">{product.name}</p><p className="text-xs text-white/45">{product.sku} · {product.categoryName ?? "Uncategorized"}</p></TableCell><TableCell className="font-mono text-lg">{product.currentStock}</TableCell><TableCell className="font-mono">{product.reorderLevel}</TableCell><TableCell>{ugx(product.currentStock * product.costPrice)}</TableCell><TableCell>{!product.isActive ? <Status tone="red">Inactive</Status> : product.currentStock <= product.reorderLevel ? <Status tone="amber">Review</Status> : <Status tone="green">Healthy</Status>}</TableCell></tr>)}</TableShell></Panel><Panel eyebrow="Controlled workflow" title="Request adjustment"><form onSubmit={submit} className="space-y-4 p-5"><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Product<select required value={form.productId} onChange={(e) => setForm({ ...form, productId: e.target.value })} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-3 text-sm text-white"><option value="">Select SKU</option>{(products.data ?? []).map((product) => <option key={product.id} value={product.id}>{product.sku} · {product.name}</option>)}</select></label><div className="grid grid-cols-2 gap-3"><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Direction<select value={form.adjustmentType} onChange={(e) => setForm({ ...form, adjustmentType: e.target.value as "IN" | "OUT" })} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-3 text-sm text-white"><option value="OUT">Decrease</option><option value="IN">Increase</option></select></label><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Quantity<Input required type="number" min="1" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })} className="mt-2 border-white/15 bg-white/5 text-white" /></label></div><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Reason<Input required minLength={5} value={form.reason} onChange={(e) => setForm({ ...form, reason: e.target.value })} placeholder="e.g. physical count variance" className="mt-2 border-white/15 bg-white/5 text-white placeholder:text-white/25" /></label><p className="text-xs leading-5 text-white/45">All adjustments remain pending until approved by an authorized manager.</p><Button disabled={requestAdjustment.isPending} className="w-full bg-[#62d8ff] font-black text-[#061a4a] hover:bg-[#91e5ff]"><Plus className="mr-2 h-4 w-4" />Submit for approval</Button></form></Panel></div><Panel eyebrow="Approval queue" title="Pending and recent adjustments" className="mt-5"><TableShell><TableHead><TableCell>Reference</TableCell><TableCell>Product</TableCell><TableCell>Type</TableCell><TableCell>Quantity</TableCell><TableCell>Status</TableCell><TableCell>Reason</TableCell></TableHead>{(adjustments.data ?? []).map((adjustment) => <tr key={adjustment.id} className="border-b border-white/10 text-white/80"><TableCell className="font-mono text-[#62d8ff]">{adjustment.adjustmentNumber}</TableCell><TableCell>{(products.data ?? []).find((p) => p.id === adjustment.productId)?.name ?? `Product #${adjustment.productId}`}</TableCell><TableCell>{adjustment.adjustmentType === "IN" ? <ArrowUpRight className="h-4 w-4 text-emerald-300" /> : <ArrowDownRight className="h-4 w-4 text-rose-300" />}</TableCell><TableCell className="font-mono">{adjustment.quantity}</TableCell><TableCell><Status tone={adjustment.status === "APPROVED" ? "green" : "amber"}>{adjustment.status}</Status></TableCell><TableCell className="max-w-xs truncate text-white/55">{adjustment.reason}</TableCell></tr>)}</TableShell></Panel><div className="mt-5 grid gap-5 xl:grid-cols-2"><Panel eyebrow="Exception intelligence" title="Live alerts"><div className="grid gap-3 p-5 sm:grid-cols-3"><div className="border border-rose-300/20 bg-rose-300/5 p-4"><p className="text-2xl font-black text-rose-200">{alerts.data?.outOfStock.length ?? 0}</p><p className="mt-1 text-xs font-bold uppercase tracking-wider text-white/55">Out of stock</p></div><div className="border border-amber-300/20 bg-amber-300/5 p-4"><p className="text-2xl font-black text-amber-200">{alerts.data?.lowStock.length ?? 0}</p><p className="mt-1 text-xs font-bold uppercase tracking-wider text-white/55">Low stock</p></div><div className="border border-cyan-300/20 bg-cyan-300/5 p-4"><p className="text-2xl font-black text-cyan-200">{alerts.data?.expiring.length ?? 0}</p><p className="mt-1 text-xs font-bold uppercase tracking-wider text-white/55">Expiring soon</p></div></div></Panel><Panel eyebrow="Authorized stock event" title="Record damage, expiry, or loss"><form onSubmit={submitLoss} className="grid gap-3 p-5 sm:grid-cols-4"><select required value={loss.productId} onChange={(e) => setLoss({ ...loss, productId: e.target.value })} className="h-10 border border-white/15 bg-[#071f56] px-2 text-xs text-white"><option value="">Select SKU</option>{(products.data ?? []).map((product) => <option key={product.id} value={product.id}>{product.sku} · {product.name}</option>)}</select><select value={loss.movementType} onChange={(e) => setLoss({ ...loss, movementType: e.target.value as "DAMAGE" | "EXPIRY" | "LOSS" })} className="h-10 border border-white/15 bg-[#071f56] px-2 text-xs text-white"><option value="DAMAGE">Damage</option><option value="EXPIRY">Expiry</option><option value="LOSS">Loss</option></select><Input required type="number" min="1" value={loss.quantity} onChange={(e) => setLoss({ ...loss, quantity: e.target.value })} placeholder="Quantity" className="border-white/15 bg-white/5 text-white placeholder:text-white/25" /><div className="flex gap-2"><Input required minLength={5} value={loss.reason} onChange={(e) => setLoss({ ...loss, reason: e.target.value })} placeholder="Reason" className="border-white/15 bg-white/5 text-white placeholder:text-white/25" /><Button disabled={recordLoss.isPending} className="bg-[#62d8ff] text-[#061a4a]"><Plus className="h-4 w-4" /></Button></div></form></Panel></div></div>;
}

function SaleComposer() {
  const products = trpc.catalog.products.useQuery(useMemo(() => ({ activeOnly: true }), []));
  const customers = trpc.catalog.customers.useQuery();
  const paymentMethods = trpc.catalog.paymentMethods.useQuery();
  const sales = trpc.operations.sales.useQuery();
  const utils = trpc.useUtils();
  const createSale = trpc.operations.createSale.useMutation({ onSuccess: (result) => { toast.success(`Invoice ${result.invoiceNumber} completed`); setItems([]); setCustomerId(""); setAmountPaid(""); void sales.refetch(); void utils.reporting.dashboard.invalidate(); void utils.catalog.products.invalidate(); }, onError: (error) => toast.error(error.message) });
  const [customerId, setCustomerId] = useState("");
  const [saleType, setSaleType] = useState<"CASH" | "CREDIT">("CASH");
  const [paymentMethodId, setPaymentMethodId] = useState("");
  const [amountPaid, setAmountPaid] = useState("");
  const [items, setItems] = useState<Array<{ productId: number; quantity: number }>>([]);
  const [productId, setProductId] = useState("");
  const [quantity, setQuantity] = useState("1");
  const addItem = () => { const selected = products.data?.find((product) => product.id === Number(productId)); if (!selected || Number(quantity) < 1) return; setItems([...items, { productId: selected.id, quantity: Number(quantity) }]); setProductId(""); setQuantity("1"); };
  const total = items.reduce((sum, item) => { const product = products.data?.find((p) => p.id === item.productId); return sum + (product?.sellingPrice ?? 0) * item.quantity; }, 0);
  const submit = (event: React.FormEvent) => { event.preventDefault(); createSale.mutate({ customerId: Number(customerId), saleType, discount: 0, tax: 0, amountPaid: Number(amountPaid || (saleType === "CASH" ? total : 0)), paymentMethodId: paymentMethodId ? Number(paymentMethodId) : undefined, items }); };
  return <div><SectionHeader eyebrow="Sales / point of sale" title="Sales control" description="Build a multi-item invoice. The server validates active products, available stock, prices, totals, payment method, and credit before committing stock-out movements." /><div className="grid gap-5 xl:grid-cols-[0.8fr_1.2fr]"><Panel eyebrow="Controlled transaction" title="New sale"><form onSubmit={submit} className="space-y-4 p-5"><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Customer<select required value={customerId} onChange={(e) => setCustomerId(e.target.value)} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-3 text-sm text-white"><option value="">Select customer</option>{(customers.data ?? []).map((customer) => <option key={customer.id} value={customer.id}>{customer.customerNumber} · {customer.name}</option>)}</select></label><div className="grid grid-cols-2 gap-3"><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Sale type<select value={saleType} onChange={(e) => setSaleType(e.target.value as "CASH" | "CREDIT")} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-3 text-sm text-white"><option value="CASH">Cash</option><option value="CREDIT">Credit</option></select></label><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Amount paid<Input type="number" min="0" value={amountPaid} onChange={(e) => setAmountPaid(e.target.value)} className="mt-2 border-white/15 bg-white/5 text-white" placeholder={saleType === "CASH" ? String(total) : "0"} /></label></div><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Payment method<select value={paymentMethodId} onChange={(e) => setPaymentMethodId(e.target.value)} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-3 text-sm text-white"><option value="">Select method</option>{(paymentMethods.data ?? []).map((method) => <option key={method.id} value={method.id}>{method.name}</option>)}</select></label><div className="border border-white/10 bg-white/5 p-4"><p className="text-xs leading-5 text-white/45">{saleType === "CREDIT" ? "Credit limit is checked against the customer's existing outstanding balance." : "Cash sales must be fully paid before confirmation."}</p></div><Button disabled={createSale.isPending || items.length === 0} className="w-full bg-[#62d8ff] font-black text-[#061a4a] hover:bg-[#91e5ff]"><Receipt className="mr-2 h-4 w-4" />Confirm sale</Button></form></Panel><Panel eyebrow="Invoice lines" title={`Draft total · ${ugx(total)}`}><div className="border-b border-white/10 p-5"><div className="grid gap-3 sm:grid-cols-[1fr_110px_auto]"><select value={productId} onChange={(e) => setProductId(e.target.value)} className="h-10 border border-white/15 bg-[#071f56] px-3 text-sm text-white"><option value="">Add a product</option>{(products.data ?? []).map((product) => <option key={product.id} value={product.id}>{product.sku} · {product.name} · {product.currentStock} available</option>)}</select><Input type="number" min="1" value={quantity} onChange={(e) => setQuantity(e.target.value)} className="border-white/15 bg-white/5 text-white" /><Button type="button" onClick={addItem} variant="outline" className="border-white/20 bg-white/5 text-white hover:bg-white/10"><Plus className="mr-2 h-4 w-4" />Add</Button></div></div><TableShell><TableHead><TableCell>Product</TableCell><TableCell>Qty</TableCell><TableCell>Unit price</TableCell><TableCell>Total</TableCell><TableCell /></TableHead>{items.map((item, index) => { const product = products.data?.find((p) => p.id === item.productId); return <tr key={`${item.productId}-${index}`} className="border-b border-white/10 text-white/80"><TableCell><p className="font-bold text-white">{product?.name}</p><p className="text-xs text-white/45">{product?.sku}</p></TableCell><TableCell className="font-mono">{item.quantity}</TableCell><TableCell>{ugx(product?.sellingPrice)}</TableCell><TableCell className="font-semibold">{ugx((product?.sellingPrice ?? 0) * item.quantity)}</TableCell><TableCell><button type="button" onClick={() => setItems(items.filter((_, i) => i !== index))} className="text-xs text-rose-200 hover:text-rose-100">Remove</button></TableCell></tr>; })}{!items.length && <tr><TableCell colSpan={5} className="py-14 text-center text-white/40">Add products to build the invoice.</TableCell></tr>}</TableShell></Panel></div><Panel eyebrow="Transaction ledger" title="Recent sales" className="mt-5"><TableShell><TableHead><TableCell>Invoice</TableCell><TableCell>Type</TableCell><TableCell>Total</TableCell><TableCell>Paid</TableCell><TableCell>Balance</TableCell><TableCell>Date</TableCell></TableHead>{(sales.data ?? []).map((sale) => <tr key={sale.id} className="border-b border-white/10 text-white/80"><TableCell className="font-mono text-[#62d8ff]">{sale.invoiceNumber}</TableCell><TableCell><Status>{sale.saleType}</Status></TableCell><TableCell>{ugx(sale.totalAmount)}</TableCell><TableCell>{ugx(sale.amountPaid)}</TableCell><TableCell>{sale.balance ? <Status tone="amber">{ugx(sale.balance)}</Status> : <Status tone="green">Settled</Status>}</TableCell><TableCell>{dateLabel(sale.createdAt)}</TableCell></tr>)}</TableShell></Panel></div>;
}

function PurchasesView() {
  const suppliers = trpc.catalog.suppliers.useQuery();
  const products = trpc.catalog.products.useQuery(useMemo(() => ({ activeOnly: true }), []));
  const purchases = trpc.operations.purchases.useQuery();
  const utils = trpc.useUtils();
  const createPurchase = trpc.operations.createPurchase.useMutation({ onSuccess: () => { toast.success("Purchase order created"); void purchases.refetch(); }, onError: (error) => toast.error(error.message) });
  const receivePurchase = trpc.operations.receivePurchase.useMutation({ onSuccess: () => { toast.success("Receipt confirmed and stock updated"); void purchases.refetch(); void utils.catalog.products.invalidate(); void utils.reporting.dashboard.invalidate(); }, onError: (error) => toast.error(error.message) });
  const [supplierId, setSupplierId] = useState(""); const [productId, setProductId] = useState(""); const [quantity, setQuantity] = useState("1"); const [unitCost, setUnitCost] = useState(""); const [notes, setNotes] = useState("");
  const submit = (event: React.FormEvent) => { event.preventDefault(); createPurchase.mutate({ supplierId: Number(supplierId), notes, items: [{ productId: Number(productId), quantity: Number(quantity), unitCost: Number(unitCost) }] }); };
  return <div><SectionHeader eyebrow="Procurement / replenishment" title="Purchase receiving" description="Create a purchase order, then confirm the receipt. Only confirmation writes stock-in movements and increases available quantity." /><div className="grid gap-5 xl:grid-cols-[0.75fr_1.25fr]"><Panel eyebrow="Inbound workflow" title="New purchase order"><form onSubmit={submit} className="space-y-4 p-5"><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Supplier<select required value={supplierId} onChange={(e) => setSupplierId(e.target.value)} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-3 text-sm text-white"><option value="">Select supplier</option>{(suppliers.data ?? []).map((supplier) => <option key={supplier.id} value={supplier.id}>{supplier.supplierNumber} · {supplier.name}</option>)}</select></label><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Product<select required value={productId} onChange={(e) => { setProductId(e.target.value); const p = products.data?.find((row) => row.id === Number(e.target.value)); setUnitCost(String(p?.costPrice ?? "")); }} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-3 text-sm text-white"><option value="">Select product</option>{(products.data ?? []).map((product) => <option key={product.id} value={product.id}>{product.sku} · {product.name}</option>)}</select></label><div className="grid grid-cols-2 gap-3"><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Quantity<Input required type="number" min="1" value={quantity} onChange={(e) => setQuantity(e.target.value)} className="mt-2 border-white/15 bg-white/5 text-white" /></label><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Unit cost<Input required type="number" min="0" value={unitCost} onChange={(e) => setUnitCost(e.target.value)} className="mt-2 border-white/15 bg-white/5 text-white" /></label></div><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Notes<Input value={notes} onChange={(e) => setNotes(e.target.value)} className="mt-2 border-white/15 bg-white/5 text-white" /></label><Button disabled={createPurchase.isPending} className="w-full bg-[#62d8ff] font-black text-[#061a4a] hover:bg-[#91e5ff]"><Plus className="mr-2 h-4 w-4" />Create purchase order</Button></form></Panel><Panel eyebrow="Inbound ledger" title="Purchase orders"><TableShell><TableHead><TableCell>Reference</TableCell><TableCell>Supplier</TableCell><TableCell>Value</TableCell><TableCell>Status</TableCell><TableCell>Action</TableCell></TableHead>{(purchases.data ?? []).map((purchase) => <tr key={purchase.id} className="border-b border-white/10 text-white/80"><TableCell className="font-mono text-[#62d8ff]">{purchase.purchaseNumber}</TableCell><TableCell>{(suppliers.data ?? []).find((s) => s.id === purchase.supplierId)?.name ?? `Supplier #${purchase.supplierId}`}</TableCell><TableCell>{ugx(purchase.totalAmount)}</TableCell><TableCell><Status tone={purchase.status === "RECEIVED" ? "green" : "amber"}>{purchase.status}</Status></TableCell><TableCell>{purchase.status !== "RECEIVED" && <Button size="sm" onClick={() => receivePurchase.mutate({ purchaseId: purchase.id })} variant="outline" className="border-emerald-300/30 bg-emerald-400/10 text-emerald-100 hover:bg-emerald-400/20"><PackageCheck className="mr-1 h-3.5 w-3.5" />Confirm receipt</Button>}</TableCell></tr>)}</TableShell></Panel></div></div>;
}

function ReturnsView() {
  const sales = trpc.operations.sales.useQuery();
  const returns = trpc.operations.salesReturns.useQuery();
  const [saleId, setSaleId] = useState(""); const [saleItemId, setSaleItemId] = useState(""); const [quantity, setQuantity] = useState("1"); const [reason, setReason] = useState("");
  const saleDetailsInput = useMemo(() => ({ saleId: Number(saleId || 0) }), [saleId]);
  const details = trpc.operations.saleDetails.useQuery(saleDetailsInput, { enabled: Boolean(saleId) });
  const createReturn = trpc.operations.createSalesReturn.useMutation({ onSuccess: () => { toast.success("Sales return approved and stock restored"); void returns.refetch(); void sales.refetch(); setSaleId(""); setSaleItemId(""); setReason(""); }, onError: (error) => toast.error(error.message) });
  const submit = (event: React.FormEvent) => { event.preventDefault(); createReturn.mutate({ saleId: Number(saleId), reason, items: [{ saleItemId: Number(saleItemId), quantity: Number(quantity) }] }); };
  return <div><SectionHeader eyebrow="Returns / traceability" title="Controlled returns" description="Every sales return must point back to an original completed invoice and a specific sale line. Approval restores stock and adjusts eligible customer exposure." /><div className="grid gap-5 xl:grid-cols-[0.7fr_1.3fr]"><Panel eyebrow="Original transaction" title="Process a sales return"><form onSubmit={submit} className="space-y-4 p-5"><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Completed invoice<select required value={saleId} onChange={(e) => { setSaleId(e.target.value); setSaleItemId(""); }} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-2 text-xs text-white"><option value="">Select invoice</option>{(sales.data ?? []).filter((sale) => sale.status === "COMPLETED").map((sale) => <option key={sale.id} value={sale.id}>{sale.invoiceNumber} · {ugx(sale.totalAmount)}</option>)}</select></label><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Original sale line<select required disabled={!saleId} value={saleItemId} onChange={(e) => setSaleItemId(e.target.value)} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-2 text-xs text-white"><option value="">Select line</option>{(details.data?.items ?? []).map((item) => <option key={item.id} value={item.id}>{item.productName} · {item.quantity - item.returnedQuantity} available to return</option>)}</select></label><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Quantity<Input required type="number" min="1" value={quantity} onChange={(e) => setQuantity(e.target.value)} className="mt-2 border-white/15 bg-white/5 text-white" /></label><label className="block text-xs font-bold uppercase tracking-wider text-white/55">Reason<Input required minLength={5} value={reason} onChange={(e) => setReason(e.target.value)} placeholder="e.g. damaged on delivery" className="mt-2 border-white/15 bg-white/5 text-white placeholder:text-white/25" /></label><Button disabled={createReturn.isPending} className="w-full bg-[#62d8ff] font-black text-[#061a4a] hover:bg-[#91e5ff]"><RefreshCw className="mr-2 h-4 w-4" />Approve return</Button></form></Panel><Panel eyebrow="Return register" title="Recent sales returns"><TableShell><TableHead><TableCell>Return</TableCell><TableCell>Original sale</TableCell><TableCell>Value</TableCell><TableCell>Reason</TableCell><TableCell>Date</TableCell></TableHead>{(returns.data ?? []).map((item) => <tr key={item.id} className="border-b border-white/10 text-white/80"><TableCell className="font-mono text-[#62d8ff]">{item.returnNumber}</TableCell><TableCell className="font-mono">#{item.saleId}</TableCell><TableCell>{ugx(item.totalAmount)}</TableCell><TableCell className="max-w-xs truncate text-white/55">{item.reason}</TableCell><TableCell>{dateLabel(item.createdAt)}</TableCell></tr>)}</TableShell></Panel></div></div>;
}

function PartnersView() {
  const suppliers = trpc.catalog.suppliers.useQuery(); const customers = trpc.catalog.customers.useQuery(); const createCustomer = trpc.catalog.createCustomer.useMutation({ onSuccess: () => { toast.success("Customer added"); void customers.refetch(); setName(""); }, onError: (error) => toast.error(error.message) }); const createSupplier = trpc.catalog.createSupplier.useMutation({ onSuccess: () => { toast.success("Supplier added"); void suppliers.refetch(); setSupplierName(""); setSupplierPhone(""); setSupplierLocation(""); }, onError: (error) => toast.error(error.message) }); const updateSupplier = trpc.catalog.updateSupplier.useMutation({ onSuccess: () => void suppliers.refetch(), onError: (error) => toast.error(error.message) }); const updateCustomer = trpc.catalog.updateCustomer.useMutation({ onSuccess: () => void customers.refetch(), onError: (error) => toast.error(error.message) }); const updateCustomerCredit = trpc.catalog.updateCustomerCredit.useMutation({ onSuccess: () => void customers.refetch(), onError: (error) => toast.error(error.message) }); const [name, setName] = useState(""); const [phone, setPhone] = useState(""); const [supplierName, setSupplierName] = useState(""); const [supplierPhone, setSupplierPhone] = useState(""); const [supplierLocation, setSupplierLocation] = useState(""); const submit = (event: React.FormEvent) => { event.preventDefault(); createCustomer.mutate({ name, telephone: phone, customerType: "Retailer", creditLimit: 0 }); };
  return <div><SectionHeader eyebrow="Counterparties / relationships" title="Customers & suppliers" description="Maintain the records that anchor credit exposure, purchase history, invoices, receipts, and statements." /><div className="grid gap-5 xl:grid-cols-2"><Panel eyebrow="Customer master" title={`${customers.data?.length ?? 0} customers`}><div className="border-b border-white/10 p-5"><form onSubmit={submit} className="grid gap-3 sm:grid-cols-[1fr_1fr_auto]"><Input required value={name} onChange={(e) => setName(e.target.value)} placeholder="Customer name" className="border-white/15 bg-white/5 text-white placeholder:text-white/25" /><Input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="Telephone" className="border-white/15 bg-white/5 text-white placeholder:text-white/25" /><Button className="bg-[#62d8ff] font-black text-[#061a4a] hover:bg-[#91e5ff]"><Plus className="mr-1 h-4 w-4" />Add</Button></form></div><TableShell><TableHead><TableCell>Customer</TableCell><TableCell>Type</TableCell><TableCell>Credit limit</TableCell><TableCell>Outstanding</TableCell><TableCell>Controls</TableCell></TableHead>{(customers.data ?? []).map((customer) => <tr key={customer.id} className="border-b border-white/10 text-white/80"><TableCell><p className="font-bold text-white">{customer.name}</p><p className="text-xs text-white/45">{customer.customerNumber}</p></TableCell><TableCell>{customer.customerType}</TableCell><TableCell>{ugx(customer.creditLimit)}</TableCell><TableCell>{customer.outstandingBalance > 0 ? <Status tone="amber">{ugx(customer.outstandingBalance)}</Status> : <Status tone="green">Clear</Status>}</TableCell><TableCell><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => { const next = window.prompt("Customer name", customer.name); if (next === null || next.trim() === "") return; const customerType = window.prompt("Customer type", customer.customerType) ?? customer.customerType; const telephone = window.prompt("Telephone", customer.telephone ?? ""); const email = window.prompt("Email", customer.email ?? ""); const address = window.prompt("Address", customer.address ?? ""); updateCustomer.mutate({ id: customer.id, name: next.trim(), customerType, telephone: telephone || null, email: email || null, address: address || null, isActive: customer.isActive }); }} className="border-white/20 bg-white/5 text-[10px] text-white">Edit profile</Button><Button size="sm" variant="outline" onClick={() => { const next = window.prompt("New credit limit (UGX)", String(customer.creditLimit)); if (next !== null && next !== "") updateCustomerCredit.mutate({ id: customer.id, creditLimit: Number(next) }); }} className="border-white/20 bg-white/5 text-[10px] text-white">Credit</Button><Button size="sm" variant="outline" onClick={() => updateCustomer.mutate({ id: customer.id, isActive: !customer.isActive, customerType: customer.customerType })} className="border-white/20 bg-white/5 text-[10px] text-white">{customer.isActive ? "Disable" : "Enable"}</Button></div></TableCell></tr>)}</TableShell></Panel><Panel eyebrow="Supplier master" title={`${suppliers.data?.length ?? 0} suppliers`}><form onSubmit={(event) => { event.preventDefault(); createSupplier.mutate({ name: supplierName, telephone: supplierPhone, location: supplierLocation }); }} className="grid gap-2 border-b border-white/10 p-4 sm:grid-cols-[1fr_1fr_1fr_auto]"><Input required value={supplierName} onChange={(e) => setSupplierName(e.target.value)} placeholder="Supplier name" className="border-white/15 bg-white/5 text-white placeholder:text-white/25" /><Input value={supplierPhone} onChange={(e) => setSupplierPhone(e.target.value)} placeholder="Telephone" className="border-white/15 bg-white/5 text-white placeholder:text-white/25" /><Input value={supplierLocation} onChange={(e) => setSupplierLocation(e.target.value)} placeholder="Location" className="border-white/15 bg-white/5 text-white placeholder:text-white/25" /><Button className="bg-[#62d8ff] text-[#061a4a]"><Plus className="h-4 w-4" /></Button></form><TableShell><TableHead><TableCell>Supplier</TableCell><TableCell>Contact</TableCell><TableCell>Location</TableCell><TableCell>Status / controls</TableCell></TableHead>{(suppliers.data ?? []).map((supplier) => <tr key={supplier.id} className="border-b border-white/10 text-white/80"><TableCell><p className="font-bold text-white">{supplier.name}</p><p className="text-xs text-white/45">{supplier.supplierNumber}</p></TableCell><TableCell>{supplier.telephone ?? supplier.email ?? "—"}</TableCell><TableCell>{supplier.location ?? "—"}</TableCell><TableCell><div className="flex items-center gap-2"><Status tone={supplier.isActive ? "green" : "red"}>{supplier.isActive ? "Active" : "Inactive"}</Status><Button size="sm" variant="outline" onClick={() => updateSupplier.mutate({ id: supplier.id, isActive: !supplier.isActive })} className="border-white/20 bg-white/5 text-[10px] text-white">{supplier.isActive ? "Disable" : "Enable"}</Button></div></TableCell></tr>)}</TableShell></Panel></div></div>;
}

function ReportsView() {
  const [from, setFrom] = useState(""); const [to, setTo] = useState(""); const [customerId, setCustomerId] = useState(""); const [supplierId, setSupplierId] = useState(""); const [overdueOnly, setOverdueOnly] = useState(false);
  const reportInput = useMemo(() => ({ from: from || undefined, to: to || undefined, customerId: customerId ? Number(customerId) : undefined }), [from, to, customerId]);
  const inventoryInput = useMemo(() => ({ from: from || undefined, to: to || undefined }), [from, to]);
  const purchaseInput = useMemo(() => ({ from: from || undefined, to: to || undefined, supplierId: supplierId ? Number(supplierId) : undefined }), [from, to, supplierId]);
  const statementInput = useMemo(() => ({ customerId: Number(customerId || 0), from: from || undefined, to: to || undefined }), [customerId, from, to]);
  const report = trpc.reporting.salesReport.useQuery(reportInput); const inventory = trpc.reporting.inventoryReport.useQuery(inventoryInput); const purchase = trpc.reporting.purchaseReport.useQuery(purchaseInput); const customers = trpc.catalog.customers.useQuery(); const suppliers = trpc.catalog.suppliers.useQuery(); const balances = trpc.reporting.customerBalances.useQuery({ overdueOnly }); const statement = trpc.reporting.customerStatement.useQuery(statementInput, { enabled: Boolean(customerId) });
  const exportReport = trpc.reporting.exportReport.useMutation({ onSuccess: (result) => { const blob = new Blob([result.content], { type: result.mimeType }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = result.filename; link.click(); URL.revokeObjectURL(url); toast.success(`${result.filename} downloaded`); }, onError: (error) => toast.error(error.message) });
  return <div><SectionHeader eyebrow="Reporting / evidence" title="Reports & exports" description="Filter the operational ledger for decision-making, customer statements, finance review, and management exports." action={<div className="flex flex-wrap gap-2"><Button onClick={() => exportReport.mutate({ report: "sales", format: "csv", from: from || undefined, to: to || undefined })} variant="outline" className="border-white/20 bg-white/5 text-white hover:bg-white/10"><FileText className="mr-2 h-4 w-4" />Sales CSV</Button><Button onClick={() => exportReport.mutate({ report: "inventory", format: "excel", from: from || undefined, to: to || undefined })} variant="outline" className="border-white/20 bg-white/5 text-white hover:bg-white/10"><FileSpreadsheet className="mr-2 h-4 w-4" />Inventory Excel</Button></div>} /><Panel eyebrow="Scope / filters" title="Report parameters"><div className="grid gap-3 p-5 sm:grid-cols-2 lg:grid-cols-5"><label className="text-xs font-bold uppercase tracking-wider text-white/55">From<Input type="date" value={from} onChange={(e) => setFrom(e.target.value)} className="mt-2 border-white/15 bg-white/5 text-white" /></label><label className="text-xs font-bold uppercase tracking-wider text-white/55">To<Input type="date" value={to} onChange={(e) => setTo(e.target.value)} className="mt-2 border-white/15 bg-white/5 text-white" /></label><label className="text-xs font-bold uppercase tracking-wider text-white/55">Customer<select value={customerId} onChange={(e) => setCustomerId(e.target.value)} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-2 text-xs text-white"><option value="">All customers</option>{(customers.data ?? []).map((customer) => <option key={customer.id} value={customer.id}>{customer.customerNumber} · {customer.name}</option>)}</select></label><label className="text-xs font-bold uppercase tracking-wider text-white/55">Supplier<select value={supplierId} onChange={(e) => setSupplierId(e.target.value)} className="mt-2 h-10 w-full border border-white/15 bg-[#071f56] px-2 text-xs text-white"><option value="">All suppliers</option>{(suppliers.data ?? []).map((supplier) => <option key={supplier.id} value={supplier.id}>{supplier.supplierNumber} · {supplier.name}</option>)}</select></label><label className="flex items-end gap-2 pb-2 text-xs font-bold uppercase tracking-wider text-white/55"><input type="checkbox" checked={overdueOnly} onChange={(e) => setOverdueOnly(e.target.checked)} /> Overdue only</label></div></Panel><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><KpiCard label="Invoices" value={String(report.data?.summary.total ?? 0)} detail="In selected date range" icon={Receipt} /><KpiCard label="Revenue" value={ugx(report.data?.summary.revenue)} detail="Confirmed invoice total" icon={WalletCards} accent="#ffc66d" /><KpiCard label="Paid" value={ugx(report.data?.summary.paid)} detail="Collected against invoices" icon={ShieldCheck} accent="#9bff9b" /><KpiCard label="Balance" value={ugx(report.data?.summary.balance)} detail="Outstanding from sales" icon={AlertTriangle} accent="#ff8ea1" /></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><Panel eyebrow="Sales performance" title="Sales report"><TableShell><TableHead><TableCell>Invoice</TableCell><TableCell>Date</TableCell><TableCell>Total</TableCell><TableCell>Balance</TableCell></TableHead>{(report.data?.rows ?? []).slice(0, 25).map((row) => <tr key={row.invoiceNumber} className="border-b border-white/10 text-white/80"><TableCell className="font-mono text-[#62d8ff]">{row.invoiceNumber}</TableCell><TableCell>{row.date}</TableCell><TableCell>{ugx(row.totalAmount)}</TableCell><TableCell>{row.balance ? <Status tone="amber">{ugx(row.balance)}</Status> : <Status tone="green">Paid</Status>}</TableCell></tr>)}</TableShell></Panel><Panel eyebrow="Inventory intelligence" title="Stock valuation"><TableShell><TableHead><TableCell>SKU / product</TableCell><TableCell>On hand</TableCell><TableCell>Reorder</TableCell><TableCell>Value</TableCell></TableHead>{(inventory.data?.stock ?? []).slice(0, 25).map((product) => <tr key={product.id} className="border-b border-white/10 text-white/80"><TableCell><p className="font-bold text-white">{product.name}</p><p className="text-xs text-white/45">{product.sku}</p></TableCell><TableCell className="font-mono">{product.currentStock}</TableCell><TableCell className="font-mono">{product.reorderLevel}</TableCell><TableCell>{ugx(product.currentStock * product.costPrice)}</TableCell></tr>)}</TableShell></Panel></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><Panel eyebrow="Procurement performance" title="Purchase report"><TableShell><TableHead><TableCell>Purchase</TableCell><TableCell>Date</TableCell><TableCell>Status</TableCell><TableCell>Value</TableCell></TableHead>{(purchase.data?.rows ?? []).slice(0, 25).map((row) => <tr key={row.purchaseNumber} className="border-b border-white/10 text-white/80"><TableCell className="font-mono text-[#62d8ff]">{row.purchaseNumber}</TableCell><TableCell>{row.date}</TableCell><TableCell><Status tone={row.status === "RECEIVED" ? "green" : "amber"}>{row.status}</Status></TableCell><TableCell>{ugx(row.totalAmount)}</TableCell></tr>)}</TableShell></Panel><Panel eyebrow="Management summary" title="Filtered operational posture"><div className="grid gap-3 p-5 sm:grid-cols-3"><div className="border border-white/10 bg-white/5 p-4"><p className="text-xs text-white/45">Purchase value</p><p className="mt-1 text-lg font-black">{ugx(purchase.data?.total)}</p></div><div className="border border-white/10 bg-white/5 p-4"><p className="text-xs text-white/45">Stock value</p><p className="mt-1 text-lg font-black">{ugx((inventory.data?.stock ?? []).reduce((sum, product) => sum + product.currentStock * product.costPrice, 0))}</p></div><div className="border border-white/10 bg-white/5 p-4"><p className="text-xs text-white/45">Overdue customers</p><p className="mt-1 text-lg font-black">{(balances.data ?? []).filter((customer) => customer.status === "OVERDUE").length}</p></div></div></Panel></div><Panel eyebrow="Customer exposure" title="Balances and overdue invoices" className="mt-5"><TableShell><TableHead><TableCell>Customer</TableCell><TableCell>Credit limit</TableCell><TableCell>Outstanding</TableCell><TableCell>Overdue</TableCell><TableCell>Status</TableCell></TableHead>{(balances.data ?? []).slice(0, 30).map((customer) => <tr key={customer.id} className="border-b border-white/10 text-white/80"><TableCell><p className="font-bold text-white">{customer.name}</p><p className="text-xs text-white/45">{customer.customerNumber}</p></TableCell><TableCell>{ugx(customer.creditLimit)}</TableCell><TableCell>{ugx(customer.outstandingBalance)}</TableCell><TableCell>{ugx(customer.overdueAmount)}</TableCell><TableCell><Status tone={customer.status === "OVERDUE" ? "red" : customer.status === "OUTSTANDING" ? "amber" : "green"}>{customer.status}</Status></TableCell></tr>)}</TableShell></Panel>{customerId && <Panel eyebrow="Customer statement" title={statement.data?.customer?.name ?? "Selected customer"} className="mt-5"><div className="grid gap-3 p-5 sm:grid-cols-3"><div><p className="text-xs text-white/45">Current outstanding</p><p className="mt-1 text-xl font-black">{ugx(statement.data?.customer?.outstandingBalance)}</p></div><div><p className="text-xs text-white/45">Invoices in range</p><p className="mt-1 text-xl font-black">{statement.data?.sales.length ?? 0}</p></div><div><p className="text-xs text-white/45">Payments in range</p><p className="mt-1 text-xl font-black">{statement.data?.payments.length ?? 0}</p></div></div></Panel>}</div>;
}

function AdminView() {
  const users = trpc.admin.users.useQuery(); const roles = trpc.admin.roles.useQuery(); const auditLogs = trpc.reporting.auditLogs.useQuery({ limit: 50 }); const currencyConfig = trpc.reporting.currencyConfig.useQuery(); const assignRole = trpc.admin.assignRole.useMutation({ onSuccess: () => { toast.success("Role assignment updated"); void users.refetch(); }, onError: (error) => toast.error(error.message) }); const setSetting = trpc.admin.setSetting.useMutation({ onSuccess: () => { (window as CurrencyWindow).__ANKOLE_CURRENCY__ = currencyValue || "UGX"; window.dispatchEvent(new Event("ankole-currency-change")); void currencyConfig.refetch(); toast.success("Currency setting updated"); }, onError: (error) => toast.error(error.message) }); const [currencyValue, setCurrencyValue] = useState("");
  return <div><SectionHeader eyebrow="Governance / access" title="Roles & audit posture" description="Access is enforced on server procedures, not merely hidden in the interface. Every important transaction writes an audit event." action={<form onSubmit={(event) => { event.preventDefault(); setSetting.mutate({ settingKey: "currency", settingValue: currencyValue || currencyConfig.data?.currency || "UGX", description: "Business display currency" }); }} className="flex items-center gap-2"><Input value={currencyValue || currencyConfig.data?.currency || "UGX"} onChange={(event) => setCurrencyValue(event.target.value.toUpperCase())} className="w-24 border-white/20 bg-white/5 text-white" aria-label="Currency code" /><Button type="submit" variant="outline" className="border-white/20 bg-white/5 text-white hover:bg-white/10">Save currency</Button></form>} /><div className="grid gap-5 xl:grid-cols-[0.8fr_1.2fr]"><Panel eyebrow="Configured access" title="Roles"><div className="grid gap-3 p-5">{(roles.data ?? []).map((role) => <div key={role.id} className="border border-white/10 bg-white/5 p-4"><div className="flex items-center gap-3"><ShieldCheck className="h-4 w-4 text-[#62d8ff]" /><p className="font-bold text-white">{role.name}</p></div><p className="mt-2 text-xs leading-5 text-white/45">{role.description}</p></div>)}</div></Panel><Panel eyebrow="Identity register" title="Users"><TableShell><TableHead><TableCell>User</TableCell><TableCell>Current label</TableCell><TableCell>Status</TableCell><TableCell>Role assignment</TableCell></TableHead>{(users.data ?? []).map((user) => <tr key={user.id} className="border-b border-white/10 text-white/80"><TableCell><p className="font-bold text-white">{user.name ?? "Unnamed user"}</p><p className="text-xs text-white/45">{user.email ?? "No email"}</p></TableCell><TableCell>{user.role}</TableCell><TableCell><Status tone={user.isActive ? "green" : "red"}>{user.isActive ? "Active" : "Inactive"}</Status></TableCell><TableCell><select defaultValue="" onChange={(e) => { if (e.target.value) assignRole.mutate({ userId: user.id, roleId: Number(e.target.value) }); }} className="h-8 border border-white/15 bg-[#071f56] px-2 text-xs text-white"><option value="">Change role</option>{(roles.data ?? []).map((role) => <option key={role.id} value={role.id}>{role.name}</option>)}</select></TableCell></tr>)}</TableShell></Panel></div><Panel eyebrow="Immutable activity trail" title="Recent audit events" className="mt-5"><TableShell><TableHead><TableCell>Time</TableCell><TableCell>Action</TableCell><TableCell>Entity</TableCell><TableCell>Reference</TableCell><TableCell>Details</TableCell></TableHead>{(auditLogs.data ?? []).map((log) => <tr key={log.id} className="border-b border-white/10 text-white/80"><TableCell>{dateLabel(log.createdAt)}</TableCell><TableCell><Status>{log.action}</Status></TableCell><TableCell>{log.entityType}</TableCell><TableCell className="font-mono">{log.entityId ?? "—"}</TableCell><TableCell className="max-w-sm truncate text-white/45">{log.details ?? "—"}</TableCell></tr>)}</TableShell></Panel></div>;
}

export default function Management() {
  const [location] = useLocation();
  const currencyConfig = trpc.reporting.currencyConfig.useQuery();
  const [, refreshCurrency] = useState(0);
  useEffect(() => {
    if (currencyConfig.data?.currency) {
      (window as CurrencyWindow).__ANKOLE_CURRENCY__ = currencyConfig.data.currency;
      refreshCurrency((value) => value + 1);
    }
  }, [currencyConfig.data?.currency]);
  useEffect(() => {
    const handleCurrencyChange = () => refreshCurrency((value) => value + 1);
    window.addEventListener("ankole-currency-change", handleCurrencyChange);
    return () => window.removeEventListener("ankole-currency-change", handleCurrencyChange);
  }, []);
  const invoiceMatch = location.match(/^\/invoices\/(\d+)$/);
  const content = invoiceMatch ? <InvoiceView saleId={Number(invoiceMatch[1])} /> : location === "/catalog" ? <CatalogView /> : location === "/inventory" ? <InventoryView /> : location === "/sales" ? <SaleComposer /> : location === "/purchases" ? <PurchasesView /> : location === "/returns" ? <ReturnsView /> : location === "/partners" ? <PartnersView /> : location === "/reports" ? <ReportsView /> : location === "/admin" ? <AdminView /> : <DashboardView />;
  return <DashboardLayout><div className="min-h-[calc(100vh-2rem)] bg-[#061a4a] text-white"><div className="mx-auto max-w-[1500px] px-2 py-5 sm:px-4 lg:px-6">{content}<Separator className="mt-10 bg-white/10" /><footer className="flex flex-col justify-between gap-2 py-5 text-[10px] font-bold uppercase tracking-[0.18em] text-white/35 sm:flex-row"><span>Ankole Soft Drinks Ltd · Buhweju District, Uganda</span><span>Blueprint operations console · UGX</span></footer></div></div></DashboardLayout>;
}
